import { useEffect, useRef, useState } from "react";
import HeroCard from "./HeroCard";
import { lerp, clamp, ease } from "./helpers";
import '../index.css';

const CARDS = [
  { id: 1,  label: "Vehicle RC",      angle: 180,   rotate: -14, z: 26 },
  { id: 2,  label: "DL Verification", angle: 147.3, rotate: 9,   z: 27 },
  { id: 3,  label: "KYC Check",       angle: 114.5, rotate: -6,  z: 28 },
  { id: 4,  label: "Aadhaar",         angle: 81.8,  rotate: 5,   z: 29 },
  { id: 5,  label: "Face Match",      angle: 49.1,  rotate: -9,  z: 29 },
  { id: 6,  label: "PAN Card",        angle: 16.4,  rotate: 12,  z: 28 },
  { id: 7,  label: "Fraud Alert",     angle: 343.6, rotate: -5,  z: 27 },
  { id: 8,  label: "Bank Verify",     angle: 310.9, rotate: 11,  z: 28 },
  { id: 9,  label: "Credit Score",    angle: 278.2, rotate: -5,  z: 29 },
  { id: 10, label: "Background Chk",  angle: 245.5, rotate: -10, z: 28 },
  { id: 11, label: "Employment",      angle: 212.7, rotate: 9,   z: 27 },
];

export default function HeroSection() {
  const [progress, setProgress] = useState(0);
  const [vw, setVw]             = useState(0);
  const sectionRef              = useRef(null);

  useEffect(() => {
    const onScroll = () => {
      const el = sectionRef.current;
      if (!el) return;
      const p = clamp(
        -el.getBoundingClientRect().top / (el.offsetHeight * 0.62),
        0, 1
      );
      setProgress(p);
    };
    window.addEventListener("scroll", onScroll, { passive: true });
    onScroll();
    return () => window.removeEventListener("scroll", onScroll);
  }, []);

  useEffect(() => {
    const update = () => setVw(window.innerWidth);
    update();
    window.addEventListener("resize", update, { passive: true });
    return () => window.removeEventListener("resize", update);
  }, []);

  const isXs     = vw > 0 && vw < 400;
  const isSm     = vw >= 400 && vw < 600;
  const isMd     = vw >= 600 && vw < 1024;
  const isLg     = vw >= 1024;
  const isMobile = vw > 0 && vw < 600;
  const isSmall  = vw > 0 && vw < 1024;

  /* ── Font sizes ── */
  const titleFontSize = isLg ? "90px"
    : isMd ? "54px"
    : isSm ? "38px"
    : "30px";

  const subtitleFontSize = isLg ? "52px"
    : isMd ? "26px"
    : isSm ? "17px"
    : "15px";

  /* ── Scroll animation (unchanged from original) ── */
  const textEnterT  = ease(clamp(progress / 0.75, 0, 1));
  const textScale   = lerp(0.92, 1.0, textEnterT);
  const textOpacity = lerp(0.75, 1.0, textEnterT);

  /*
   * ── MOBILE LAYOUT STRATEGY ──
   *
   * Problem: on desktop the title/subtitle sit BEHIND the cards (zIndex 15/16
   * vs cards 26-29) because the card orbit is wide enough that cards ring
   * the edges and the center text shows through cleanly.
   *
   * On mobile the orbit is tiny so cards cluster right over the text.
   *
   * Solution for mobile/tablet:
   *   1. Give title + subtitle zIndex 30 (above cards) — they render on top.
   *   2. Pin TITLE to the top zone of the viewport.
   *   3. Anchor SUBTITLE to the bottom zone of the viewport.
   *   4. Shift the card orbit CENTER point downward (via cardCenterOffsetVh)
   *      so the ring sits in the middle band between title and subtitle.
   *
   * Desktop: completely unchanged — title/subtitle centered behind cards.
   */

  // Shift card orbit center downward on mobile so it occupies the middle zone
  const cardCenterOffsetVh = isLg ? 0 : isMd ? 5 : isSm ? 8 : 8;

  return (
    <div ref={sectionRef} style={{ height: "300vh", position: "relative" }}>
      <div
        id="home-banner"
        style={{
          position: "sticky",
          top: 30,
          height: "100vh",
          overflow: "hidden",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
        }}
      >
        {/* Grid background */}
        <div
          style={{
            position: "absolute",
            inset: 0,
            backgroundImage:
              "linear-gradient(rgba(255,255,255,0.03) 1px, transparent 1px)," +
              "linear-gradient(90deg, rgba(255,255,255,0.03) 1px, transparent 1px)",
            backgroundSize: "clamp(32px, 4vw, 48px) clamp(32px, 4vw, 48px)",
          }}
        />

        {/* ── TITLE ──
            Desktop: no top override, flex parent centers it, zIndex 15 (behind cards)
            Mobile/tablet: pinned to top zone, zIndex 30 (in front of cards) */}
        <div
          style={{
            position: "absolute",
            ...(isLg
              ? {
                  // ── DESKTOP (unchanged) ──
                  zIndex: 15,
                }
              : {
                  // ── MOBILE / TABLET ──
                  top: isMd ? "6%" : isSm ? "5%" : "4%",
                  zIndex: 30,
                }
            ),
            left: "50%",
            transform: `translateX(-50%) scale(${textScale})`,
            textAlign: "center",
            width: "92vw",
            maxWidth: "1300px",
            opacity: textOpacity,
            willChange: "transform, opacity",
            padding: isSmall ? "0 16px" : "0",
          }}
        >
          <h1
            style={{
              fontFamily: "Inter",
              fontSize: titleFontSize,
              fontWeight: 900,
              color: "white",
              margin: 0,
              lineHeight: 1.05,
              whiteSpace: "normal",
              overflowWrap: "break-word",
              wordBreak: "break-word",
              letterSpacing: "-0.02em",
            }}
          >
            Deception from
            <br />
            Click to the Doorstep
          </h1>
        </div>

        {/* ── SUBTITLE ──
            Desktop: top: 62%, zIndex 16, translateX(-50%) (unchanged)
            Mobile/tablet: bottom-anchored, zIndex 30 */}
        <div
          style={{
            position: "absolute",
            ...(isLg
              ? {
                  // ── DESKTOP (unchanged) ──
                  top: "62%",
                  left: "50%",
                  transform: `translateX(-50%) scale(${textScale})`,
                  zIndex: 16,
                }
              : {
                  // ── MOBILE / TABLET ──
                  bottom: isMd ? "6%" : isSm ? "5%" : "4%",
                  left: "50%",
                  transform: `translateX(-50%) scale(${textScale})`,
                  zIndex: 30,
                }
            ),
            width: isMobile ? "88vw" : "92vw",
            maxWidth: "1300px",
            textAlign: "center",
            pointerEvents: "none",
            opacity: textOpacity,
            willChange: "transform, opacity",
            padding: isSmall ? "0 8px" : "0",
          }}
        >
          <p
            style={{
              fontSize: subtitleFontSize,
              fontWeight: 500,
              color: "white",
              margin: 0,
              lineHeight: 1.3,
              opacity: 0.88,
              marginTop: isLg ? "30px" : "0",
            }}
          >
            A closer look at the risks in India's gig workforce.
          </p>
        </div>

        {/* ── Cards layer (zIndex 25 — between title and subtitle on desktop,
            below title/subtitle on mobile) ── */}
        <div
          style={{
            position: "absolute",
            inset: 0,
            pointerEvents: "none",
            overflow: "hidden",
            zIndex: 25,
          }}
        >
          {CARDS.map(c => (
            <HeroCard
              key={c.id}
              card={c}
              progress={progress}
              vw={vw}
              cardCenterOffsetVh={cardCenterOffsetVh}
            />
          ))}
        </div>
      </div>
    </div>
  );
}
